DROP TABLE IF EXISTS `car_listings_master`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `car_listings_master` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `brand` varchar(64) DEFAULT NULL,
  `model` varchar(128) DEFAULT NULL,
  `submodel` varchar(128) DEFAULT NULL,
  `year` smallint DEFAULT NULL,
  `gear` varchar(32) DEFAULT NULL,
  `engine` varchar(64) DEFAULT NULL,
  `color` varchar(64) DEFAULT NULL,
  `mileage` int DEFAULT NULL,
  `price` bigint DEFAULT NULL,
  `priceType` varchar(32) DEFAULT NULL,
  `sourceName` varchar(64) DEFAULT NULL,
  `sourceType` varchar(32) DEFAULT NULL,
  `sourceUrl` text,
  `externalId` varchar(128) DEFAULT NULL,
  `dateRecorded` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_source_external` (`sourceName`,`externalId`),
  KEY `idx_brand` (`brand`),
  KEY `idx_model` (`model`),
  KEY `idx_year` (`year`),
  KEY `idx_price` (`price`),
  KEY `idx_mileage` (`mileage`)
) ENGINE=InnoDB AUTO_INCREMENT=31208 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
